#!/usr/bin/env python3
"""Generate leakcheck_peer.sh for a workspace from its answer_key.json.
Usage: gen_leakcheck.py <workspace_dir>"""
import json, sys
from pathlib import Path

ws = Path(sys.argv[1])
k = json.load(open(ws / "key/answer_key.json"))
jingle = sorted({p["term_a"] for p in k["pairs"] if p["expected"] == "noMatchDespiteSimilarity"})
a_only = sorted({p["term_a"] for p in k["pairs"]} - set(jingle))
b_only = sorted({p["term_b"] for p in k["pairs"]} - set(jingle))
def arr(xs): return " ".join(f"'{x}'" for x in xs)
script = f"""#!/usr/bin/env bash
# leakcheck_peer.sh — GENERATED by gen_leakcheck.py from key/answer_key.json. Do not hand-edit.
set -euo pipefail
mode="${{1:?mode}}"; f="${{2:?file}}"
a_only=({arr(a_only)})
b_only=({arr(b_only)})
jingle=({arr(jingle)})
meta=('exactMatch' 'broadMatch' 'narrowMatch' 'relatedMatch' 'noMatch' '\\bbroader\\b' '\\bnarrower\\b' 'shared core' '\\bresidue' '\\bplanted\\b' 'answer key' 'community A' 'community B' '\\bjingle\\b')
fail=0
check() {{ local pat="$1" label="$2"; if grep -qiE "$pat" "$f"; then echo "LEAK[$label]: $pat"; fail=1; fi }}
case "$mode" in
  cross-a) for t in "${{b_only[@]}}"; do check "$t" "b-term-in-a"; done ;;
  cross-b) for t in "${{a_only[@]}}"; do check "$t" "a-term-in-b"; done ;;
  meta)    for t in "${{meta[@]}}"; do check "$t" "meta"; done ;;
  def)     for t in "${{a_only[@]}}" "${{b_only[@]}}" "${{jingle[@]}}"; do check "$t" "term-in-def"; done
           for t in "${{meta[@]}}"; do check "$t" "meta"; done ;;
  *) echo "unknown mode $mode"; exit 2 ;;
esac
exit $fail
"""
(ws / "leakcheck_peer.sh").write_text(script)
print("leakcheck_peer.sh generated:", len(a_only), "a-terms,", len(b_only), "b-terms, jingles:", jingle)
